verify:
choices = {o: choices[n] for o, n in {'D': 'A', 'A': 'B', 'B': 'C', 'C': 'D'}.items()}; answer = {'A': 'D', 'B': 'A', 'C': 'B', 'D': 'C'}[answer]  # shuffled: original letters
t = symbols('t')
def g(k):
    return value(choices[k].split('=')[1])
target = {1: 200000*Rational(1005, 1000)**12, 2: 200000*Rational(1005, 1000)**24}
def ok(e):
    return all(e.subs(t, k) == v for k, v in target.items())
assert ok(g(answer))
assert all(not ok(g(k)) for k in choices if k != answer)
